// spec: .qa/e2e/specs/achievements.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Достижения', () => {
  test('AC-01 Сетка 6 достижений — полученные и неполученные различимы, без дублей #6a86f7ed @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/journey` → блок «הישגים».
    await page.goto('/journey');
    await expect(page.getByRole('heading', { name: 'הישגים' })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);

    // 2. Для каждого из 6 названий: вхождения, aria-label, role, цвет текста.
    const achieved = ['תפילה ראשונה', '3 ימים רצופים', '30 תפילות', '100 תפילות'];
    const notAchieved = ['שבוע שלם', 'חודש רצוף'];
    const all = ['תפילה ראשונה', '3 ימים רצופים', 'שבוע שלם', '30 תפילות', 'חודש רצוף', '100 תפילות'];

    // Ровно 6 карточек, каждое название — по одному разу
    await expect(page.getByLabel(/: (הושג|טרם הושג)$/)).toHaveCount(6);
    for (const name of all) {
      await expect(page.getByLabel(new RegExp(`^${name}: `))).toHaveCount(1);
    }

    for (const name of achieved) {
      const card = page.getByLabel(`${name}: הושג`, { exact: true });
      await expect(card).toHaveCount(1);
      await expect(card).toHaveAttribute('role', 'button');
      await expect(card.getByText(name, { exact: true })).toHaveCSS('color', 'rgb(35, 59, 83)');
    }
    for (const name of notAchieved) {
      const card = page.getByLabel(`${name}: טרם הושג`, { exact: true });
      await expect(card).toHaveCount(1);
      expect(await card.getAttribute('role')).not.toBe('button');
      await expect(page.getByRole('button', { name: `${name}: טרם הושג` })).toHaveCount(0);
      await expect(card.getByText(name, { exact: true })).toHaveCSS('color', 'rgb(95, 119, 142)');
    }
  });
});
